def build_agent(sandbox):
    # Calculate density to stay within mass limit
    total_area = (1.0 * 0.08) * 2 + (0.08 * 0.53)
    density = 1.5 / total_area

    # Horizontal beam at y=1.92m to separate small and medium particles
    beam1 = sandbox.add_static_beam(x=5.7, y=1.92, width=1.0, height=0.08, density=density)

    # Horizontal beam at y=2.45m to separate medium and large particles
    beam2 = sandbox.add_static_beam(x=5.7, y=2.45, width=1.0, height=0.08, density=density)

    # Vertical support beam connecting the horizontal beams
    beam3 = sandbox.add_static_beam(x=5.7, y=2.185, width=0.08, height=0.53, density=density)

    # Reduce bounce to prevent particle deflection
    sandbox.set_material_properties(beam1, restitution=0.0)
    sandbox.set_material_properties(beam2, restitution=0.0)
    sandbox.set_material_properties(beam3, restitution=0.0)

    return beam1

